import urllib.request
import zipfile
import os
import urllib.error


def task_func(
    url: str,
    save_path: str = "downloaded_file.zip",
    extract_path: str = "extracted_files",
) -> str:
    result: str | None = None
    downloaded_file = False

    try:
        with urllib.request.urlopen(url) as response:
            data = response.read()

        with open(save_path, "wb") as file:
            downloaded_file = True
            file.write(data)

        if not zipfile.is_zipfile(save_path):
            result = "ZIP Error: downloaded file is not a valid ZIP archive"
        else:
            try:
                os.makedirs(extract_path, exist_ok=True)
                with zipfile.ZipFile(save_path, "r") as zip_ref:
                    bad_member = zip_ref.testzip()
                    if bad_member is not None:
                        raise zipfile.BadZipFile(
                            f"corrupted ZIP file: first bad file is {bad_member}"
                        )
                    zip_ref.extractall(extract_path)
                result = extract_path
            except zipfile.BadZipFile as e:
                message = str(e).strip()
                result = f"ZIP Error: {message or 'corrupted ZIP file'}"
            except zipfile.LargeZipFile as e:
                result = f"ZIP Error: {e}"
            except RuntimeError as e:
                result = f"ZIP Error: {e}"
            except OSError as e:
                result = f"File Error: {e}"

    except urllib.error.URLError as e:
        reason = getattr(e, "reason", None)
        if reason is None:
            reason = str(e)
        result = f"URL Error: {reason}"
    except OSError as e:
        result = f"File Error: {e}"
    except Exception as e:
        result = f"Unexpected Error: {e}"
    finally:
        if downloaded_file and os.path.exists(save_path):
            try:
                os.remove(save_path)
            except OSError as e:
                cleanup_error = f"File Error: failed to delete downloaded ZIP file: {e}"
                if result == extract_path:
                    result = cleanup_error
                elif result is None:
                    result = cleanup_error
                else:
                    result = f"{result} | {cleanup_error}"

    return result if result is not None else "Unexpected Error: unknown failure"
